/**
 * invite_email.php
 *
 * Sends ONE school invitation per execution using the Brevo Transactional Email API.
 * Intended for Hostinger Cron every 10 minutes.
 * Production sending is enforced by this script: Monday-Friday, 09:00-15:00 Asia/Kuala_Lumpur (GMT+8).
 *
 * Test:
 *   /invite_email?mode=test
 *   /invite_email?mode=test&code=CEA4088
 *
 * Manual:
 *   /invite_email?mode=manual&code=CEA4088
 *
 * Manual mode sends immediately to the selected school's real contact_email and bypasses:
 * sending day/time, Cron secret, state, unsubscribed status, download status,
 * previous invitation status and the 14-day resend interval.
 * A valid school code, valid contact_email and jpn = 1 are still required.
 *
 * Test mode always sends to aidilazhar@me.com and never updates invite_email/invite_date/invite_read. The selected school must have jpn = 1.
 * Production excludes schools that unsubscribed or already downloaded the programme file.
 * A school is eligible when never sent, manually reset (invite_email = 0), or the DATE part of invite_date is more than 14 days old.
 * invite_date stores the full Kuala Lumpur date/time; email text displays the date only.
 * invite_read is a boolean flag: 0 = not opened, 1 = opened.
 * It is reset to 0 after every successful invitation or resend; brevo_webhook.php sets it to 1 on an open event.
 */

declare(strict_types=1);

function loadInviteEnv(string $file): void
{
    if (!is_file($file) || !is_readable($file)) {
        return;
    }

    $lines = file($file, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
    if ($lines === false) {
        return;
    }

    foreach ($lines as $line) {
        $line = trim($line);
        if ($line === '' || str_starts_with($line, '#') || !str_contains($line, '=')) {
            continue;
        }

        [$name, $value] = explode('=', $line, 2);
        $name = trim($name);
        $value = trim($value);

        if ($name === '' || getenv($name) !== false) {
            continue;
        }

        if (
            strlen($value) >= 2 &&
            (($value[0] === '"' && $value[strlen($value) - 1] === '"') ||
             ($value[0] === "'" && $value[strlen($value) - 1] === "'"))
        ) {
            $value = substr($value, 1, -1);
        }

        putenv($name . '=' . $value);
        $_ENV[$name] = $value;
    }
}

