function respond(string $message, int $status = 200): never
{
    http_response_code($status);
    if (PHP_SAPI === 'cli') {
        echo $message . PHP_EOL;
    } else {
        header('Content-Type: text/plain; charset=UTF-8');
        echo $message;
    }
    exit;
}

