function requestValue(string $name, string $default = ''): string
{
    if (PHP_SAPI === 'cli') {
        global $argv;
        foreach (($argv ?? []) as $argument) {
            $prefix = '--' . $name . '=';
            if (str_starts_with($argument, $prefix)) {
                return trim(substr($argument, strlen($prefix)));
            }
        }
        return $default;
    }

    return trim((string) ($_GET[$name] ?? $default));
}

function h(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

function malayDate(DateTimeInterface $date): string
{
    $months = [
        1 => 'Januari', 2 => 'Februari', 3 => 'Mac', 4 => 'April',
        5 => 'Mei', 6 => 'Jun', 7 => 'Julai', 8 => 'Ogos',
        9 => 'September', 10 => 'Oktober', 11 => 'November', 12 => 'Disember',
    ];

    return $date->format('j') . ' ' . $months[(int) $date->format('n')] . ' ' . $date->format('Y');
}

function makeUnsubscribeToken(string $schoolCode, string $secret): string
{
    return hash_hmac('sha256', strtoupper($schoolCode), $secret);
}

function sendBrevo(array $payload, string $apiKey): array
{
    if (!function_exists('curl_init')) {
        throw new RuntimeException('PHP cURL extension is required.');
    }

    $json = json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    if ($json === false) {
        throw new RuntimeException('Unable to encode Brevo request.');
    }

    $ch = curl_init(BREVO_ENDPOINT);
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CONNECTTIMEOUT => 15,
        CURLOPT_TIMEOUT => 45,
        CURLOPT_HTTPHEADER => [
            'accept: application/json',
            'api-key: ' . $apiKey,
            'content-type: application/json',
        ],
        CURLOPT_POSTFIELDS => $json,
        CURLOPT_SSL_VERIFYPEER => true,
        CURLOPT_SSL_VERIFYHOST => 2,
    ]);

    $body = curl_exec($ch);
    if ($body === false) {
        $error = curl_error($ch);
        curl_close($ch);
        throw new RuntimeException('Brevo connection failed: ' . $error);
    }

    $status = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    $decoded = json_decode($body, true);
    return [
        'status' => $status,
        'body' => $body,
        'json' => is_array($decoded) ? $decoded : [],
    ];
}

