$apiKey = trim((string) (getenv('BREVO_API_KEY') ?: ''));
$senderEmail = trim((string) (getenv('BREVO_SENDER_EMAIL') ?: ''));
$senderName = trim((string) (getenv('BREVO_SENDER_NAME') ?: 'Metadata Berhad'));
$replyToEmail = trim((string) (getenv('BREVO_REPLY_TO_EMAIL') ?: $senderEmail));
$targetState = trim((string) (getenv('INVITE_STATE') ?: 'Pahang'));
$unsubscribeSecret = trim((string) (getenv('INVITE_UNSUBSCRIBE_SECRET') ?: ''));

if ($apiKey === '' || $senderEmail === '') {
    respond('Brevo is not configured. Add BREVO_API_KEY and BREVO_SENDER_EMAIL to .env.', 500);
}
if ($unsubscribeSecret === '') {
    respond('INVITE_UNSUBSCRIBE_SECRET is not configured in .env.', 500);
}
if (!filter_var($senderEmail, FILTER_VALIDATE_EMAIL)) {
    respond('BREVO_SENDER_EMAIL is invalid.', 500);
}
if ($replyToEmail !== '' && !filter_var($replyToEmail, FILTER_VALIDATE_EMAIL)) {
    respond('BREVO_REPLY_TO_EMAIL is invalid.', 500);
}

$mode = strtolower(requestValue('mode'));
$requestedCode = strtoupper(requestValue('code'));
$isTest = $mode === 'test';
$isManual = $mode === 'manual';

if ($isManual && $requestedCode === '') {
    respond('Manual mode requires a school code. Example: /invite_email?mode=manual&code=CEA4088', 400);
}

// -----------------------------------------------------------------------------
// PRODUCTION SENDING WINDOW
// -----------------------------------------------------------------------------
// Test mode remains available outside this window.
// Production email is allowed only Monday-Friday from 09:00:00 through
// 15:00:59 in Asia/Kuala_Lumpur (GMT+8). With a 10-minute Cron this means
// sends at 09:00, 09:10, ... 11:50 and 15:00 only.
$nowMalaysia = new DateTimeImmutable('now', new DateTimeZone('Asia/Kuala_Lumpur'));
$malaysiaWeekday = (int) $nowMalaysia->format('N'); // 1 = Monday, 7 = Sunday
$malaysiaTime = $nowMalaysia->format('H:i:s');

$withinProductionWindow =
    $malaysiaWeekday >= 1 &&
    $malaysiaWeekday <= 5 &&
    $malaysiaTime >= '09:00:00' &&
    $malaysiaTime <= '15:00:59';

if (!$isTest && !$isManual && !$withinProductionWindow) {
    respond(
        'Outside invitation sending window. Production email is allowed Monday-Friday, 09:00-15:00 Asia/Kuala_Lumpur (GMT+8). Current Malaysia time: ' .
        $nowMalaysia->format('Y-m-d H:i:s l') . '.',
        200
    );
}

if (!$isTest && !$isManual && PHP_SAPI !== 'cli') {
    $cronSecret = trim((string) (getenv('INVITE_CRON_SECRET') ?: ''));
    $requestKey = requestValue('key');
    if ($cronSecret === '' || $requestKey === '' || !hash_equals($cronSecret, $requestKey)) {
        respond('Forbidden. Run production invitations from Cron/CLI.', 403);
    }
}

if ($isTest && PHP_SAPI !== 'cli') {
    $testSecret = trim((string) (getenv('INVITE_TEST_SECRET') ?: ''));
    if ($testSecret !== '') {
        $requestKey = requestValue('key');
        if ($requestKey === '' || !hash_equals($testSecret, $requestKey)) {
            respond('Forbidden.', 403);
        }
    }
}

try {
    if ($isManual) {
        $stmt = $pdo->prepare(
            'SELECT id, school_code, school_name, contact_email, state, download_file, invite_email, invite_date, unsubscribed, COALESCE(jpn, 0) AS jpn
             FROM schools
             WHERE UPPER(school_code) = ?
               AND COALESCE(jpn, 0) = 1
             LIMIT 1'
        );
        $stmt->execute([$requestedCode]);

        $school = $stmt->fetch();
        if (!$school) {
            respond('Manual send failed: school code ' . $requestedCode . ' was not found or jpn is not enabled (jpn = 1).', 404);
        }

        $recipientEmail = trim((string) ($school['contact_email'] ?? ''));
        if ($recipientEmail === '' || !filter_var($recipientEmail, FILTER_VALIDATE_EMAIL)) {
            respond(
                'Manual send failed: school ' . $requestedCode . ' does not have a valid contact email address.',
                400
            );
        }
    } elseif ($isTest) {
        if ($requestedCode !== '') {
            $stmt = $pdo->prepare(
                'SELECT id, school_code, school_name, contact_email, state, download_file, invite_email, invite_date, unsubscribed, COALESCE(jpn, 0) AS jpn
                 FROM schools
                 WHERE school_code = ?
                   AND COALESCE(jpn, 0) = 1
                 LIMIT 1'
            );
            $stmt->execute([$requestedCode]);
        } else {
            $stmt = $pdo->prepare(
                'SELECT id, school_code, school_name, contact_email, state, download_file, invite_email, invite_date, unsubscribed, COALESCE(jpn, 0) AS jpn
                 FROM schools
                 WHERE state = ?
                   AND COALESCE(jpn, 0) = 1
                 ORDER BY id
                 LIMIT 1'
            );
            $stmt->execute([$targetState]);
        }

        $school = $stmt->fetch();
        if (!$school) {
            respond('Test failed: no matching school with jpn = 1 was found in the database.', 404);
        }
        $recipientEmail = TEST_EMAIL;
    } else {
        $stmt = $pdo->prepare(
            'SELECT id, school_code, school_name, contact_email, state, download_file, invite_email, invite_date, unsubscribed, COALESCE(jpn, 0) AS jpn
             FROM schools
             WHERE state = ?
               AND COALESCE(jpn, 0) = 1
               AND COALESCE(unsubscribed, 0) = 0
               AND COALESCE(download_file, 0) = 0
               AND (
                    COALESCE(invite_email, 0) = 0
                    OR invite_date IS NULL
                    OR DATE(invite_date) < DATE_SUB(DATE(UTC_TIMESTAMP() + INTERVAL 8 HOUR), INTERVAL 14 DAY)
               )
               AND contact_email IS NOT NULL
               AND TRIM(contact_email) <> \'\'
             ORDER BY CASE
                          WHEN COALESCE(invite_email, 0) = 0 OR invite_date IS NULL THEN 0
                          ELSE 1
                      END,
                      invite_date ASC,
                      id ASC
             LIMIT 100'
        );
        $stmt->execute([$targetState]);

        $school = null;
        foreach ($stmt->fetchAll() as $candidate) {
            $candidateEmail = trim((string) $candidate['contact_email']);
            if (filter_var($candidateEmail, FILTER_VALIDATE_EMAIL)) {
                $school = $candidate;
                break;
            }
        }

        if (!$school) {
            respond('No pending or resend-eligible school with jpn = 1 and a valid email address was found.');
        }

        $recipientEmail = trim((string) $school['contact_email']);
    }

    $schoolName = trim((string) $school['school_name']);
    $schoolCode = strtoupper(trim((string) $school['school_code']));
    if ($schoolName === '' || $schoolCode === '') {
        respond('School record is missing school name or school code.', 500);
    }

    $sentAtMalaysia = $nowMalaysia;

    $email = buildInvitationEmail(
        $schoolName,
        $schoolCode,
        $metadataLogoBase64,
        $signatureBase64,
        $equipmentPreviewBase64,
        $websiteQrBase64,
        $whatsappQrBase64,
        $unsubscribeSecret,
        $sentAtMalaysia,
        $isTest
    );

    $payload = [
        'sender' => [
            'name' => $senderName,
            'email' => $senderEmail,
        ],
        'to' => [[
            'name' => $schoolName,
            'email' => $recipientEmail,
        ]],
        'subject' => $email['subject'],
        'htmlContent' => $email['html'],
        'textContent' => $email['text'],
        'headers' => [
            'List-Unsubscribe' => '<' . $email['unsubscribe_url'] . '>',
        ],
        'tags' => array_values(array_filter([
            'school-invitation',
            $isManual ? 'manual-invitation' : null,
            strtolower((string) preg_replace('/[^A-Za-z0-9_-]/', '', $schoolCode)),
        ])),
    ];

    // Attach the JPN Pahang approval letter as a real PDF attachment.
    // The required production file is: /download/jpnp.pdf
    $jpnpPdfPath = __DIR__ . '/download/jpnp.pdf';

    if (!is_file($jpnpPdfPath) || !is_readable($jpnpPdfPath)) {
        error_log('Required JPN Pahang attachment is missing or unreadable: ' . $jpnpPdfPath);
        respond('Email was not sent because /download/jpnp.pdf could not be found or read.', 500);
    }

    $jpnpPdfBinary = file_get_contents($jpnpPdfPath);
    if ($jpnpPdfBinary === false || $jpnpPdfBinary === '') {
        error_log('Unable to read JPN Pahang attachment: ' . $jpnpPdfPath);
        respond('Email was not sent because /download/jpnp.pdf could not be read.', 500);
    }

    $payload['attachment'] = [[
        'content' => base64_encode($jpnpPdfBinary),
        'name' => 'jpnp.pdf',
    ]];

    if ($replyToEmail !== '') {
        $payload['replyTo'] = [
            'name' => $senderName,
            'email' => $replyToEmail,
        ];
    }

    $result = sendBrevo($payload, $apiKey);
    if ($result['status'] !== 201) {
        $brevoMessage = (string) ($result['json']['message'] ?? $result['body'] ?? 'Unknown Brevo error');
        error_log('Brevo invite failed for ' . $schoolCode . ' HTTP ' . $result['status'] . ': ' . $brevoMessage);
        respond('Email was not sent. Brevo returned HTTP ' . $result['status'] . ': ' . $brevoMessage, 502);
    }

    $messageId = (string) ($result['json']['messageId'] ?? '');

    if (!$isTest) {
        if ($isManual) {
            $update = $pdo->prepare(
                'UPDATE schools
                 SET invite_email = 1,
                     invite_date = ?,
                     invite_read = 0
                 WHERE id = ?
                   AND COALESCE(jpn, 0) = 1'
            );
        } else {
            $update = $pdo->prepare(
                'UPDATE schools
                 SET invite_email = 1,
                     invite_date = ?,
                     invite_read = 0
                 WHERE id = ?
                   AND COALESCE(jpn, 0) = 1
                   AND COALESCE(unsubscribed, 0) = 0'
            );
        }

        $update->execute([
            $sentAtMalaysia->format('Y-m-d H:i:s'),
            (int) $school['id'],
        ]);

        if ($update->rowCount() !== 1) {
            error_log('Brevo accepted invite but DB tracking update failed. School: ' . $schoolCode . ', Message ID: ' . $messageId);
            respond('Brevo accepted the email, but the database invitation status could not be updated. Check logs before retrying.', 500);
        }
    }

    respondInvitationSuccess(
        $schoolCode,
        $schoolName,
        $recipientEmail,
        $messageId,
        $isTest,
        $isManual
    );
} catch (Throwable $e) {
    error_log('invite_email.php error: ' . $e->getMessage());
    respond('Invitation email error: ' . $e->getMessage(), 500);
}
